template:
struct Clean { name: String }
struct Dirty { name: String }
struct Buffer<S> { state: S }

impl Buffer<Clean> {
    fn fill(⟦slot1⟧) -> Buffer<Dirty> {
        Buffer { state: Dirty { name: ⟦slot2⟧ } }
    }
}

fn main() {
    let buf = Buffer { state: Clean { name: String::from("data") } };
    let _dirty = buf.fill();
}

tests:
#[test]
fn test_transition() {
    let buf = Buffer { state: Clean { name: String::from("test") } };
    let dirty = buf.fill();
    assert_eq!(dirty.state.name, "test");
}
